import click
import sqlite3
import csv
import io
import sys
from datetime import datetime

STAGES = ['lead', 'qualified', 'proposal', 'won', 'lost']
WEIGHTS = {'lead': 0.1, 'qualified': 0.3, 'proposal': 0.6, 'won': 1.0, 'lost': 0.0}


def get_db(db_path):
    conn = sqlite3.connect(db_path)
    conn.execute("PRAGMA foreign_keys=ON")
    conn.row_factory = sqlite3.Row
    return conn


def init_schema(conn):
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS contacts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            name TEXT NOT NULL,
            company TEXT,
            phone TEXT
        );
        CREATE TABLE IF NOT EXISTS opportunities (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            contact_email TEXT NOT NULL REFERENCES contacts(email),
            amount REAL NOT NULL,
            stage TEXT NOT NULL DEFAULT 'lead',
            close_date TEXT
        );
    """)
    conn.commit()


def lookup_contact(conn, email):
    row = conn.execute("SELECT * FROM contacts WHERE email = ?", (email,)).fetchone()
    return row


@click.group()
@click.option('--db', default='deals.db', help='Path to SQLite database')
@click.pass_context
def cli(ctx, db):
    ctx.ensure_object(dict)
    ctx.obj['db'] = db


@cli.command()
@click.pass_context
def init(ctx):
    conn = get_db(ctx.obj['db'])
    try:
        init_schema(conn)
    finally:
        conn.close()


@cli.group()
def contact():
    pass


@contact.command()
@click.option('--email', required=True)
@click.option('--name', required=True)
@click.option('--company', default=None)
@click.option('--phone', default=None)
@click.pass_context
def add(ctx, email, name, company, phone):
    if '@' not in email:
        click.echo("Error: email must contain @", err=True)
        sys.exit(1)
    conn = get_db(ctx.obj['db'])
    try:
        conn.execute(
            "INSERT INTO contacts (email, name, company, phone) VALUES (?, ?, ?, ?)",
            (email, name, company, phone),
        )
        conn.commit()
    except sqlite3.IntegrityError:
        click.echo("Error: duplicate email", err=True)
        sys.exit(1)
    finally:
        conn.close()


@contact.command(name='list')
@click.option('--company', default=None)
@click.pass_context
def list_contacts(ctx, company):
    conn = get_db(ctx.obj['db'])
    try:
        if company is not None:
            rows = conn.execute(
                "SELECT * FROM contacts WHERE company = ?", (company,)
            ).fetchall()
        else:
            rows = conn.execute("SELECT * FROM contacts").fetchall()
        for r in rows:
            click.echo(f"{r['email']} | {r['name']} | {r['company']} | {r['phone']}")
    finally:
        conn.close()


@contact.command()
@click.argument('email')
@click.pass_context
def show(ctx, email):
    conn = get_db(ctx.obj['db'])
    try:
        row = lookup_contact(conn, email)
        if row is None:
            click.echo("Error: contact not found", err=True)
            sys.exit(1)
        click.echo(f"email: {row['email']}")
        click.echo(f"name: {row['name']}")
        click.echo(f"company: {row['company']}")
        click.echo(f"phone: {row['phone']}")
    finally:
        conn.close()


@cli.group()
def opp():
    pass


@opp.command()
@click.option('--title', required=True)
@click.option('--contact', required=True)
@click.option('--amount', type=float, required=True)
@click.option('--stage', default='lead', type=click.Choice(STAGES))
@click.option('--close', default=None)
@click.pass_context
def add(ctx, title, contact, amount, stage, close):
    if amount <= 0:
        click.echo("Error: amount must be greater than 0", err=True)
        sys.exit(1)
    if close is not None:
        try:
            datetime.strptime(close, "%Y-%m-%d")
        except ValueError:
            click.echo("Error: close must be YYYY-MM-DD", err=True)
            sys.exit(1)
    conn = get_db(ctx.obj['db'])
    try:
        c = lookup_contact(conn, contact)
        if c is None:
            click.echo("Error: unknown contact", err=True)
            sys.exit(1)
        conn.execute(
            "INSERT INTO opportunities (title, contact_email, amount, stage, close_date) VALUES (?, ?, ?, ?, ?)",
            (title, contact, amount, stage, close),
        )
        conn.commit()
        new_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()['id']
        click.echo(new_id)
    finally:
        conn.close()


@opp.command(name='list')
@click.option('--stage', default=None, type=click.Choice(STAGES))
@click.option('--contact', default=None)
@click.option('--sort', default=None, type=click.Choice(['amount', 'close']))
@click.pass_context
def list_opps(ctx, stage, contact, sort):
    conn = get_db(ctx.obj['db'])
    try:
        clauses = []
        params = []
        if stage is not None:
            clauses.append("stage = ?")
            params.append(stage)
        if contact is not None:
            clauses.append("contact_email = ?")
            params.append(contact)
        where = "WHERE " + " AND ".join(clauses) if clauses else ""
        order = ""
        if sort == 'amount':
            order = "ORDER BY amount DESC"
        elif sort == 'close':
            order = "ORDER BY close_date DESC NULLS LAST"
        query = f"SELECT * FROM opportunities {where} {order}"
        rows = conn.execute(query, params).fetchall()
        for r in rows:
            click.echo(f"{r['id']} | {r['title']} | {r['contact_email']} | {r['amount']} | {r['stage']} | {r['close_date']}")
    finally:
        conn.close()


@opp.command()
@click.argument('id', type=int)
@click.option('--stage', required=True, type=click.Choice(STAGES))
@click.pass_context
def move(ctx, id, stage):
    conn = get_db(ctx.obj['db'])
    try:
        row = conn.execute("SELECT * FROM opportunities WHERE id = ?", (id,)).fetchone()
        if row is None:
            click.echo("Error: opportunity not found", err=True)
            sys.exit(1)
        if row['stage'] in ('won', 'lost'):
            click.echo(f"Error: cannot move from terminal stage '{row['stage']}'", err=True)
            sys.exit(1)
        conn.execute(
            "UPDATE opportunities SET stage = ? WHERE id = ?",
            (stage, id),
        )
        conn.commit()
    finally:
        conn.close()


@opp.command()
@click.argument('id', type=int)
@click.pass_context
def show(ctx, id):
    conn = get_db(ctx.obj['db'])
    try:
        row = conn.execute("SELECT * FROM opportunities WHERE id = ?", (id,)).fetchone()
        if row is None:
            click.echo("Error: opportunity not found", err=True)
            sys.exit(1)
        click.echo(f"id: {row['id']}")
        click.echo(f"title: {row['title']}")
        click.echo(f"contact_email: {row['contact_email']}")
        click.echo(f"amount: {row['amount']}")
        click.echo(f"stage: {row['stage']}")
        click.echo(f"close_date: {row['close_date']}")
    finally:
        conn.close()


@cli.command()
@click.pass_context
def pipeline(ctx):
    conn = get_db(ctx.obj['db'])
    try:
        rows = conn.execute(
            "SELECT stage, COUNT(*) as cnt, COALESCE(SUM(amount), 0) as total FROM opportunities GROUP BY stage"
        ).fetchall()
        data = {r['stage']: (r['cnt'], r['total']) for r in rows}
        click.echo("Stage | Count | Total")
        for s in STAGES:
            cnt, total = data.get(s, (0, 0))
            click.echo(f"{s} | {cnt} | {total}")
    finally:
        conn.close()


@cli.group()
def report():
    pass


@report.command(name='won')
@click.option('--from', 'from_date', required=True)
@click.option('--to', required=True)
@click.pass_context
def won(ctx, from_date, to):
    try:
        datetime.strptime(from_date, "%Y-%m-%d")
    except ValueError:
        click.echo("Error: --from must be YYYY-MM-DD", err=True)
        sys.exit(1)
    try:
        datetime.strptime(to, "%Y-%m-%d")
    except ValueError:
        click.echo("Error: --to must be YYYY-MM-DD", err=True)
        sys.exit(1)
    if from_date > to:
        click.echo("Error: --from must be before or equal to --to", err=True)
        sys.exit(1)
    conn = get_db(ctx.obj['db'])
    try:
        row = conn.execute(
            "SELECT COALESCE(SUM(amount), 0) as total FROM opportunities WHERE stage = 'won' AND close_date BETWEEN ? AND ?",
            (from_date, to),
        ).fetchone()
        click.echo(f"${row['total']:.2f}")
    finally:
        conn.close()


@cli.command()
@click.pass_context
def forecast(ctx):
    conn = get_db(ctx.obj['db'])
    try:
        rows = conn.execute("SELECT amount, stage FROM opportunities").fetchall()
        total = sum(r['amount'] * WEIGHTS.get(r['stage'], 0.0) for r in rows)
        click.echo(f"${total:.2f}")
    finally:
        conn.close()


@cli.command(name='export')
@click.pass_context
def export(ctx):
    conn = get_db(ctx.obj['db'])
    try:
        rows = conn.execute("SELECT * FROM opportunities").fetchall()
        with open('opportunities.csv', 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['id', 'title', 'contact_email', 'amount', 'stage', 'close_date'])
            for r in rows:
                writer.writerow([r['id'], r['title'], r['contact_email'], r['amount'], r['stage'], r['close_date']])
    finally:
        conn.close()


@cli.command(name='import')
@click.pass_context
def import_opps(ctx):
    conn = get_db(ctx.obj['db'])
    try:
        with open('opportunities.csv', 'r', newline='') as f:
            reader = csv.reader(f)
            header = next(reader)  # skip header
            for row in reader:
                eid, title, contact_email, amount, stage, close_date = row
                c = lookup_contact(conn, contact_email)
                if c is None:
                    click.echo(f"Error: unknown contact {contact_email}", err=True)
                    sys.exit(1)
                conn.execute(
                    "INSERT INTO opportunities (id, title, contact_email, amount, stage, close_date) VALUES (?, ?, ?, ?, ?, ?)",
                    (int(eid), title, contact_email, float(amount), stage, close_date),
                )
        conn.commit()
    finally:
        conn.close()

